#pragma once

#include <open62541/server.h>

#include <optional>
#include <string>
#include <vector>

#include "core/simulation.hpp"
#include "opcua/method_handlers.hpp"

namespace seatrace::sim::opcua {

inline constexpr std::string_view kNamespaceUri = "urn:seatrace:simulator";
inline constexpr std::string_view kNotice =
    "SIMULATED DATA - not a real vessel. All values are generated by the SeaTrace simulator and "
    "must not be used for navigation or operations.";

// Builds the SeaTrace address space (see docs/opc-ua-model.md) and publishes simulation state
// into it. All NodeIds are string NodeIds in the namespace urn:seatrace:simulator.
class AddressSpace {
 public:
  // Creates every node. Throws std::runtime_error when open62541 rejects a node. `server` and
  // `control` must outlive this object.
  AddressSpace(UA_Server* server, const Simulation& simulation, ControlContext& control);

  UA_UInt16 namespace_index() const { return ns_; }

  // Writes the current simulation snapshot: measurements, states, heartbeat, ActiveScenarios.
  // Nothing of a vessel in telemetry interruption is written (values and timestamps freeze).
  // Returns the number of writes the server rejected (always 0 unless the model is broken).
  std::size_t publish(const Simulation& simulation);

  // Writes ActiveScenarios if it changed since the last write.
  std::size_t publish_scenarios(const Simulation& simulation);

 private:
  struct EquipmentNodes {
    const Equipment* equipment;
    std::string state_id;
    std::string health_id;
    std::vector<std::string> measurement_ids;  // same order as equipment->sensors()
  };
  struct VesselNodes {
    const Vessel* vessel;
    std::vector<EquipmentNodes> equipment;
  };

  void build(const Simulation& simulation, ControlContext& control);
  void add_vessel(const Vessel& vessel);
  void add_equipment(const UA_NodeId& vessel_node, const Vessel& vessel, const Equipment& equipment,
                     VesselNodes& nodes);

  void add_object(const UA_NodeId& parent, UA_UInt32 reference_type, const std::string& id,
                  std::string_view browse_name, std::string_view display_name);
  // Read-only String property (HasProperty) with a constant value.
  void add_property(const UA_NodeId& parent, const std::string& id, std::string_view browse_name,
                    std::string_view value);
  // Read-only variable (HasComponent) whose value is written by publish().
  void add_variable(const UA_NodeId& parent, const std::string& id, std::string_view browse_name,
                    const UA_DataType& type, std::string_view description);
  void add_variable_node(const UA_NodeId& parent, UA_UInt32 reference_type,
                         UA_UInt32 type_definition, const std::string& id,
                         std::string_view browse_name, const UA_DataType& type, const void* initial,
                         std::string_view description);

  // Returns false when the server rejected the write.
  bool write(const std::string& id, const UA_DataType& type, const void* value,
             UA_StatusCode status, std::optional<SimTime> source_time);
  bool write_string(const std::string& id, std::string_view value, SimTime source_time);

  UA_Server* server_;
  UA_UInt16 ns_;
  std::vector<VesselNodes> vessels_;
  std::string last_scenarios_json_;
};

}  // namespace seatrace::sim::opcua
